import{z as s,x as p,o as t,c as A,q as i,j as E,D as e,d as o,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Attribution Graphs 归因图","description":"","frontmatter":{"title":"Attribution Graphs 归因图","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/attribution-graphs.md","filePath":"llm/attribution-graphs.md","lastUpdated":1791413859000}'),B={name:"llm/attribution-graphs.md"};function d(h,a,u,m,g,c){const r=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=i('<h1 id="attribution-graphs-归因图" tabindex="-1">Attribution Graphs 归因图 <a class="header-anchor" href="#attribution-graphs-归因图" aria-label="Permalink to &quot;Attribution Graphs 归因图&quot;">​</a></h1><div class="epigraph"><p>归因图描述模型为某一提示产生目标 token 所走的计算步骤：节点是激活的特征、提示嵌入、重构误差与输出 logits，边是节点之间的线性效应。</p><footer>—— Ameisen, Lindsey, Pearce, Gurnee et al., Circuit Tracing: Revealing Computational Graphs in Language Models, Transformer Circuits Thread, 2025</footer></div><p>稀疏自编码器把残差里的方向拆成可命名特征，但特征清单还不是机制。机制要回答：在这一次前向里，哪些特征激活了、它们怎样把输入写成输出。Anthropic 在 2025 年的电路追踪工作里把这一次前向收成一张图——归因图（attribution graph）。图是针对单条提示、单个目标 token 的局部计算描述，不是网络的全局线路图。读懂这张图，才谈得上对「这一次为什么说出这个词」做假设，再用干预去证伪。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>权重与激活都是高维的。直接对残差做梯度归因，得到的是稠密影响场，人读不动，也难对应到概念。把 MLP 换成稀疏特征之后，计算仍是多层、多位置、带注意力混合的。若只列出「哪些特征在这一层亮了」，仍缺少边：亮了之后去了哪里、对最终 logits 的贡献是多少。</p><p>归因图要解决的就是把一次前向写成可剪枝的加权有向图。节点必须比神经元更可解释，边必须有可加性，否则无法把「贡献」从输出反推回输入。Ameisen 等人采用的近似是：在替换模型里，特征之间的效应在激活阈值之上接近线性，于是一条边可以标一个标量。</p><h3 id="全局电路与单次归因不是同一对象" tabindex="-1">全局电路与单次归因不是同一对象 <a class="header-anchor" href="#全局电路与单次归因不是同一对象" aria-label="Permalink to &quot;全局电路与单次归因不是同一对象&quot;">​</a></h3><p>经典电路工作（如 IOI）寻找跨提示稳定的子图。归因图默认不保证稳定性：换一句提示，节点集合可以完全不同。它更接近「这一次的计算轨迹」。若要升级成可复用电路，需要在多条提示上对齐特征、看边是否重复出现。把单次图直接叫做「模型的电路」，会把偶然激活当成结构。</p><p><span class="marginnote">图中的「特征」来自交叉层转码器等替换组件，不是原模型 MLP 神经元。边的线性性也是对替换模型而言的。原模型与替换模型之间的重构误差会作为额外节点进入图；忽略这些误差节点，等于假装替换是无损的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先构造替换模型：用交叉层转码器（cross-layer transcoder）近似各层 MLP，把残差更新写成稀疏特征的加和。注意力仍按原模型运行，但特征可以跨层读。对给定提示做一次前向，记录哪些特征在哪些位置超过阈值。</p><p><span class="marginnote">术语翻译：「交叉层转码器」可以理解成给每一层 MLP 配的「逐字翻译员」——它把 MLP 那锅混在一起的稠密计算，翻译成一串大多为 0 的「特征开关 + 强度」。翻译必然有损耗，损耗多少就记在「重构误差」这个节点里，图上不藏。</span></p><p>然后算边。目标是某个输出 logit 或 logit 差。从输出反传或用线性化的雅可比，得到特征 \\(i\\) 对特征 \\(j\\) 的局部线性效应，作为有向边权重。输入 token 嵌入、注意力读写、重构误差也进入节点集。得到的原始图通常极大，必须剪枝：删掉对目标贡献低于阈值的节点与边，只留支撑该 logit 的主干。</p><h3 id="节点类型与剪枝" tabindex="-1">节点类型与剪枝 <a class="header-anchor" href="#节点类型与剪枝" aria-label="Permalink to &quot;节点类型与剪枝&quot;">​</a></h3><p>节点至少四类：提示 token 嵌入、稀疏特征（带层与位置）、重构误差、输出 logits。边表示「在这次前向的线性化下，源对汇的贡献」。剪枝不是装饰。Anthropic 的可视化工具依赖人能看完的稀疏图；阈值太松则回到稠密归因，太紧则把真正的并行通路剪掉。配套论文 <em>On the Biology of a Large Language Model</em> 在 Claude 3.5 Haiku 上展示了多条被剪过的图，并强调剪枝后仍要用干预核对。</p><p>Dunefsky 等人更早用转码器做特征电路，归因图把「特征-特征线性贡献」系统化成可浏览对象，并补上误差节点与输出节点，使图在账本意义上闭合：目标 logit 的变动应能被入边之和（加阈值非线性）解释。</p><p><span class="marginnote">直觉类比：「账本闭合」就是复式记账的借贷相抵——目标 logit 涨了 2.3，就该有一堆入边的贡献加起来约等于 2.3；若主干只凑出 1.1，剩下的大头来自误差节点，那这张图讲的故事就撑不住。先对账，再讲故事。</span></p>',17)),(t(),E(l,null,{default:e(()=>[n(r,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E6%9E%84%E9%80%A0%E6%9B%BF%E6%8D%A2%E6%A8%A1%E5%9E%8B%EF%BC%9A%E8%BD%AC%E7%A0%81%E5%99%A8%E6%8D%A2%20MLP%22%5D%20--%3E%20S2%5B%22%E5%8D%95%E6%9D%A1%E6%8F%90%E7%A4%BA%E5%89%8D%E5%90%91%EF%BC%9A%E8%AE%B0%E5%BD%95%E8%B6%85%E9%98%88%E5%80%BC%E7%89%B9%E5%BE%81%22%5D%0A%20%20S2%20--%3E%20S3%5B%22%E4%BB%8E%E7%9B%AE%E6%A0%87%20logit%20%E5%8F%8D%E4%BC%A0%EF%BC%9A%E7%AE%97%E7%BA%BF%E6%80%A7%E5%8C%96%E8%BE%B9%E6%9D%83%22%5D%0A%20%20S3%20--%3E%20S4%5B%22%E5%89%AA%E6%9E%9D%EF%BC%9A%E7%95%99%E4%B8%8B%E6%94%AF%E6%92%91%E4%B8%BB%E5%B9%B2%22%5D%0A%20%20S4%20--%3E%20S5%5B%22%E5%A4%B9%E6%8C%81%E7%89%B9%E5%BE%81%E5%81%9A%E5%B9%B2%E9%A2%84%E9%AA%8C%E8%AF%81%22%5D%0A%20%20S5%20--%3E%20PASS%5B%22%E5%9B%BE%E4%B8%8E%E8%A1%8C%E4%B8%BA%E4%B8%80%E8%87%B4%EF%BC%9A%E5%81%87%E8%AE%BE%E5%8D%87%E7%BA%A7%22%5D%0A%20%20S5%20--%3E%20FAIL%5B%22%E8%A1%8C%E4%B8%BA%E4%B8%8D%E5%8A%A8%EF%BC%9A%E6%95%85%E4%BA%8B%E4%BD%9C%E5%BA%9F%E6%88%96%E6%94%B9%E5%9B%BE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么边可以当线性？替换模型里，特征激活是对残差的稀疏编码，下一层特征的预激活往往是当前特征的线性函数再过阈值。在激活已发生的局部，阈值的次梯度把计算收成分段线性，于是沿这条路径的一阶归因有定义。注意力混合会破坏纯 MLP 的线性，因此早期归因图对「为何注意某个位置」解释不足；Kamath、Ameisen 等人后续用 QK 归因把注意力分数也写成特征双线性项，再并入图。</p><h3 id="从图到可检验假设" tabindex="-1">从图到可检验假设 <a class="header-anchor" href="#从图到可检验假设" aria-label="Permalink to &quot;从图到可检验假设&quot;">​</a></h3><p>图给出的是假设生成器，不是证明。一条从「法语特征」到「下一词是法文」的路径，只说明在线性化账本里这条路有质量。要确认，需要把该特征夹到对照值，看输出是否按图预言的方向移动。生物学论文里的案例（多步推理、诗歌韵脚、安全拒答的内部冲突）都走「图上找路径 → 夹持特征 → 看行为」这一循环。</p><p><span class="marginnote">直觉类比：「夹持」相当于生物学里的敲除实验——不动实验方案，只把怀疑中的那个基因（特征）按住，看性状（输出）变不变。变，说明它在因果链上；不变，说明图上那条漂亮的边只是相关性。归因图负责「提名」，夹持负责「定罪」。</span></p><p><span class="marginnote">线性效应可加，不表示概念正交。两个特征可以对同一 logit 都有正边，却在语义上纠缠。读图时优先看相对贡献和干预结果，不要把粗边直接翻译成「模型在用这个概念思考」。</span></p><p>账本闭合还要求把误差算进去。若误差节点对输出的贡献与特征主干相当，这张图就不能当机制解释，只能当「替换模型在这一提示上失真」的诊断。这是归因图相对朴素梯度热力图的诚实之处：它把解释不了的残差显式画出来。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>归因图绑定提示与目标 token，计算与存储都随上下文长度、活跃特征数增长。生产模型上通常只对短提示、单一目标做交互式分析。特征字典本身会过时：换一套转码器，节点身份就变，跨检查点对比图很难。剪枝阈值、目标是「单个 logit」还是「正确类减错误类」，都会改变主干长什么样。</p><p>它也不能替代权重级电路分析。图解释的是这一次用了哪些特征通路，不自动给出可迁移的算法描述。把归因图当演示工具很合适；当安全审计的唯一证据则不够——必须配干预、配替换误差报告、配多提示重复。</p><p><span class="marginnote">可视化会诱使人讲故事。一条漂亮的左到右路径往往是剪枝后的主干，并行的小边被扔掉了。写结论前应回看未剪枝贡献表：若主干只占总效应的一小半，故事就不成立。</span></p>',11)),(t(),E(l,null,{default:e(()=>[n(r,{id:"mermaid-83",class:"mermaid",graph:"flowchart%20LR%0A%20%20Tok%5B%22%E6%8F%90%E7%A4%BA%E5%B5%8C%E5%85%A5%22%5D%20--%3E%20F1%5B%22%E7%A8%80%E7%96%8F%E7%89%B9%E5%BE%81%22%5D%0A%20%20F1%20--%3E%20F2%5B%22%E4%B8%8B%E6%B8%B8%E7%89%B9%E5%BE%81%22%5D%0A%20%20Err%5B%22%E9%87%8D%E6%9E%84%E8%AF%AF%E5%B7%AE%22%5D%20--%3E%20F2%0A%20%20F2%20--%3E%20Logit%5B%22%E7%9B%AE%E6%A0%87%20logit%22%5D%0A%20%20F1%20--%3E%20Logit%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>归因图是单次前向的局部计算图：节点为特征、嵌入、误差与 logits，边为线性化贡献。</li><li>它依赖替换模型（交叉层转码器）把 MLP 写成稀疏、近似线性的特征运算。</li><li>原始图必须剪枝才可读；剪枝后必须用特征夹持验证，并检查误差节点的贡献。</li><li>单次图不等于全局电路；跨提示对齐之后才谈得上稳定机制。</li><li>注意力通路需要额外的 QK 归因才能进入同一张图。</li><li>出处：Ameisen, Lindsey, Pearce, Gurnee et al., <em>Circuit Tracing: Revealing Computational Graphs in Language Models</em>, Transformer Circuits, 2025；应用见 Lindsey et al., <em>On the Biology of a Large Language Model</em>, 2025。</li></ul>',2))])}const b=s(B,[["render",d]]);export{D as __pageData,b as default};
